        p_prefix = p[:star_idx]
        p_suffix = p[star_idx+1:]
        n = len(s)
        m = len(p)

        # If the prefix or suffix is longer than s, it's impossible
        if len(p_prefix) > n or len(p_suffix) > n:
            return False

        # Try all possible starting positions in s for the prefix
        for i in range(n - len(p_prefix) + 1):
            if s[i:i+len(p_prefix)] == p_prefix:
                # Check if the suffix can match the remaining part of s
                # The suffix must start at or after position i
                start_suffix = i + len(p_prefix)
                # The suffix can be placed starting from start_suffix up to n - len(p_suffix)
