class Solution:
    def countSubarrays(self, nums: List[int]) -> int:
        count = 0
        n = len(nums)
        for i in range(n - 2):
            a = nums[i]
            b = nums[i + 1]
            c = nums[i + 2]
            if a + c == b // 2 and (a + c) * 2 == b:
                # Ensure exact half (avoid floating point issues)
                if (a + c) * 2 == b:
                    count += 1
        return count
