from typing import List
import math

class Solution:
    def maxLength(self, nums: List[int]) -> int:
        def gcd(a: int, b: int) -> int:
            while b:
                a, b = b, a % b
            return a

        def lcm(a: int, b: int) -> int:
            return a // gcd(a, b) * b

        n = len(nums)
        max_len = 0

        # Brute-force all subarrays (O(n^3) due to recomputing prod/gcd/lcm)
        # Given constraints n <= 100, this is acceptable.
        for i in range(n):
            prod = 1
            g = 0
            l = 1
            for j in range(i, n):
                val = nums[j]
                prod *= val
                if g == 0:
                    g = val
                else:
                    g = gcd(g, val)
                l = lcm(l, val)
                if prod == g * l:
                    max_len = max(max_len, j - i + 1)
        return max_len
