import collections

class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        # Build adjacency maps for day 1 and day 2 (only forward directions)
        day1 = collections.defaultdict(dict)
        for i, (src, tgt) in enumerate(pairs1):
            day1[src][tgt] = rates1[i]

        day2 = collections.defaultdict(dict)
        for i, (src, tgt) in enumerate(pairs2):
            day2[src][tgt] = rates2[i]

        def get_rate(c1: str, c2: str, days: collections.defaultdict) -> float:
            """Return direct conversion rate from c1 to c2 if it exists, else 1.0."""
            if c1 in days and c2 in days[c1]:
                return days[c1][c2]
            return 1.0

        def get_path_rate(start: str, end: str, graph: collections.defaultdict) -> float:
            """Return the maximum multiplicative rate along any path from start to end in the given graph.
               Since there are no cycles and no contradictions, we can just do DFS with memoization.
            """
            memo = {}

            def dfs(u: str) -> float:
                if u == end:
                    return 1.0
                if u in memo:
                    return memo[u]

                best = 1.0
                if u in graph:
                    for v, rate in graph[u].items():
                        res = dfs(v)
                        if res > best:
                            best = res
                memo[u] = best
                return best

            return dfs(start)

        # All possible currencies that appear in either day's pairs or are the initial/target of interest
        currencies = set()
        currencies.add(initialCurrency)
        for s, t in pairs1:
            currencies.add(s); currencies.add(t)
        for s, t in pairs2:
            currencies.add(s); currencies.add(t)

        # We will compute, for each currency X, the maximum amount of X we can get starting from initialCurrency
        # by using ONLY day1 conversions (possibly zero steps).
        day1_max = {c: 1.0 for c in currencies}
        day1_max[initialCurrency] = 1.0

        # BFS/DFS to propagate day1 multipliers
        q = collections.deque([initialCurrency])
        while q:
            u = q.popleft()
            if u in day1_max:
                cur = day1_max[u]
                for v, rate in day1[u].items():
                    new_val = cur * rate
                    if new_val > day1_max[v]:
                        day1_max[v] = new_val
                        q.append(v)

        # Similarly for day2
        day2_max = {c: 1.0 for c in currencies}
        day2_max[initialCurrency] = 1.0

        q = collections.deque([initialCurrency])
        while q:
