        # Option A: Do nothing on day1 and do nothing on day2 -> amount = 1.0
        # Option B: Only day1 conversions (already captured in day1_max for each currency)
        # Option C: Only day2 conversions (captured in day2_max for each currency)
        # Option D: Day1 then Day2:
        #   For each currency X reachable after day1, we can convert X->...->initialCurrency using day2.
        #   The multiplier for X->initialCurrency on day2 is:
        #       rate_day2(X, initialCurrency) = product of rates along some path from X to initialCurrency on day2.
        #   But we need the maximum over all paths, so we compute for each X the max rate from X to initialCurrency on day2.
        #   However, our day2_max was from initialCurrency forward. We need reverse.
        #   Since there are no cycles, we can build a reverse graph for day2 and compute max rates from each node to initialCurrency.

        # Build reverse graph for day2
        rev_day2 = collections.defaultdict(dict)
        for src, targets in day2.items():
            for tgt, rate in targets.items():
                # rate from src->tgt implies inverse rate tgt->src for reverse
                rev_day2[tgt][src] = 1.0 / rate

        # Compute max rate from each currency to initialCurrency on day2
        # We'll do a DFS from each currency to initialCurrency, but better: run a reverse BFS from initialCurrency in rev_day2
        # to get max multiplier from each node to initialCurrency.

        max_to_initial = {c: 1.0 for c in currencies}
        max_to_initial[initialCurrency] = 1.0

        q = collections.deque([initialCurrency])
        while q:
            u = q.popleft()
            for v, rate in rev_day2[u].items():
                new_val = rate * max_to_initial[u]
                if new_val > max_to_initial[v]:
                    max_to_initial[v] = new_val
                    q.append(v)

        # Now for each currency X reachable on day1, the best final amount is:
        #   day1_max[X] * max_to_initial[X]
        ans = 1.0  # Option A: do nothing
        for x in currencies:
            if x in day1_max:
                val = day1_max[x] * max_to_initial[x]
                if val > ans:
                    ans = val

        # Also consider doing nothing on day1 but using day2 to go back to initialCurrency:
        #   That's already covered because day1_max[x] = 1.0 for x = initialCurrency, and max_to_initial[initialCurrency] = 1.0.
        #   For other currencies, if we start with initialCurrency, do nothing on day1, we have 1.0 of initialCurrency.
        #   Then on day2 we can convert initialCurrency -> ... -> initialCurrency? That would be a cycle, but problem says no cycles.
        #   So this case yields exactly 1.0, which is covered by ans = 1.0.

        # Additionally, we could convert on day2 first? No, the problem states: 
        # "using rates1 on day 1, followed by any number of additional conversions, including zero, using rates2 on day 2."
        # So day2 conversions can only happen after day1 conversions (or if we do zero day1 conversions).
        # Therefore, our considered cases are complete.

        return ans
