from typing import List

class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 10**9 + 7
        m, n = len(grid), len(grid[0])

        # dp[i][j][x] = number of paths from (0,0) to (i,j) with XOR sum x
        # Since x is in [0,15], we can use a list of size 16
        dp = [[[0] * 16 for _ in range(n)] for _ in range(m)]

        # Initialize starting cell
        dp[0][0][grid[0][0]] = 1

        # Fill the first row
        for j in range(1, n):
            prev_xor = dp[0][j-1]
            for x in range(16):
                if dp[0][j-1][x] > 0:
                    new_x = x ^ grid[0][j]
                    dp[0][j][new_x] = (dp[0][j][new_x] + dp[0][j-1][x]) % MOD

        # Fill the first column
        for i in range(1, m):
            for x in range(16):
                if dp[i-1][0][x] > 0:
                    new_x = x ^ grid[i][0]
                    dp[i][0][new_x] = (dp[i][0][new_x] + dp[i-1][0][x]) % MOD

        # Fill the rest of the grid
        for i in range(1, m):
            for j in range(1, n):
                val = grid[i][j]
                # From top
                for x in range(16):
                    if dp[i-1][j][x] > 0:
                        new_x = x ^ val
                        dp[i][j][new_x] = (dp[i][j][new_x] + dp[i-1][j][x]) % MOD
                # From left
                for x in range(16):
                    if dp[i][j-1][x] > 0:
                        new_x = x ^ val
                        dp[i][j][new_x] = (dp[i][j][new_x] + dp[i][j-1][x]) % MOD

        # Result is the number of paths to (m-1, n-1) with XOR sum k
        return dp[m-1][n-1][k]
