class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # dp[i][d] = length of the longest valid subsequence ending at index i
        # with the last absolute difference equal to d.
        # Since nums[i] <= 300, max possible difference is 299.
        max_diff = 300
        dp = [[0] * (max_diff + 1) for _ in range(n)]

        for i in range(n):
            dp[i][0] = 1  # difference 0 not really possible unless same element, but we handle >0

        for i in range(n):
            for j in range(i + 1, n):
                diff = abs(nums[i] - nums[j])
                # We want to extend a subsequence ending at i with last difference d
                # such that d >= diff.
                # If diff == 0, we can extend any d >= 0 (but diff=0 only if equal values)
                # For diff > 0, we look at all d >= diff.

                # Optimization: we can maintain for each j the best length for each last diff.
                # But since max_diff is small (300), we can iterate.

                best_len = 0
                if diff == 0:
                    # If difference is 0, we can extend any previous last diff d >= 0
                    # But practically, if we have same value, diff=0, and we require non-increasing.
                    # So we can extend any d >= 0.
                    for d in range(max_diff + 1):
                        if dp[i][d] > best_len:
                            best_len = dp[i][d]
                else:
                    for d in range(diff, max_diff + 1):
                        if dp[i][d] > best_len:
                            best_len = dp[i][d]

                if best_len > 0:
                    dp[j][diff] = best_len + 1
                else:
                    dp[j][diff] = 1  # subsequence of length 1

        # The answer is the maximum value in dp table
        ans = 0
        for i in range(n):
            for d in range(max_diff + 1):
                if dp[i][d] > ans:
                    ans = dp[i][d]
        return ans
