class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        # Check if all elements are already distinct
        if len(nums) == len(set(nums)):
            return 0

        operations = 0
        while len(nums) >= 3:
            operations += 1
            nums = nums[3:]
            # After removing 3 elements, check again if distinct
            if len(nums) == len(set(nums)):
                break

        # If still not distinct and array has fewer than 3 elements,
        # we must remove all remaining elements
        if len(nums) != len(set(nums)):
            operations += 1

        return operations
