from typing import List

class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        MOD = 10**9 + 7
        m, n = len(grid), len(grid[0])

        # dp[i][j][x] = number of paths from (0,0) to (i,j) with XOR sum x
        # Since x is in [0,15], we can use a 2D array for each cell
        dp = [[[0] * 16 for _ in range(n)] for _ in range(m)]

        # Initialize starting cell
        dp[0][0][grid[0][0]] = 1

        # Fill the DP table
        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue

                current_val = grid[i][j]

                # From top
                if i > 0:
                    for x in range(16):
                        if dp[i-1][j][x] > 0:
                            new_x = x ^ current_val
                            dp[i][j][new_x] = (dp[i][j][new_x] + dp[i-1][j][x]) % MOD

                # From left
                if j > 0:
                    for x in range(16):
                        if dp[i][j-1][x] > 0:
                            new_x = x ^ current_val
                            dp[i][j][new_x] = (dp[i][j][new_x] + dp[i][j-1][x]) % MOD

        # Result is the number of paths to (m-1, n-1) with XOR sum k
        return dp[m-1][n-1][k]
