class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # dp[i] = length of the longest valid subsequence ending at index i
        dp = [1] * n
        # last_diff[i] = the absolute difference between the last two elements in the optimal subsequence ending at i
        last_diff = [0] * n

        for i in range(1, n):
            max_len = 1
            best_prev_diff = 0  # We want to extend a subsequence where last_diff <= current_diff

            for j in range(i):
                diff = abs(nums[i] - nums[j])
                if diff >= last_diff[j]:
                    # We can extend the subsequence ending at j
                    if dp[j] > max_len:
                        max_len = dp[j]
                        best_prev_diff = last_diff[j]

            dp[i] = max_len
            last_diff[i] = diff

        return max(dp)
